// 型別只在編譯時約束；數值邊界仍須執行時檢查。

type Result<T, E> = { ok: true; value: T } | { ok: false; error: E };

async function measure(turns: number): Promise<Result<number, string>> {
  return turns < 0 ? { ok: false, error: '負數' } : { ok: true, value: turns * 2 };
}
async function total(values: number[]): Promise<number> {
  const settled = await Promise.all(values.map(measure));
  return settled.reduce((sum, item) => item.ok ? sum + item.value : sum, 0);
}

